@dataclass
class Welford:
    """Online mean/variance via Welford's algorithm (single pass).

    Internally *shifted*: all updates operate on (x - shift) where shift is
    anchored at the first observation. Without this, a running mean near 1e9
    rounds at ulp(1e9) ~ 1.2e-7 on every update and the variance drifts;
    shifting keeps every intermediate quantity O(1) regardless of offset.
    Variance is shift-invariant; the reported mean adds the shift back.
    """

    n: int = 0
    shift: float = 0.0
    mean_inner: float = 0.0          # mean of (x - shift)
    m2: float = 0.0                  # sum of squared deviations (shift-invariant)

    def push(self, x: float) -> None:
        if self.n == 0:
            self.shift = x
        y = x - self.shift
        self.n += 1
        delta = y - self.mean_inner
        self.mean_inner += delta / self.n
        delta2 = y - self.mean_inner
        self.m2 += delta * delta2

    @property
    def mean(self) -> float:
        return self.shift + self.mean_inner if self.n else 0.0

    @property
    def variance(self) -> float:

